        try:
            with open(full, 'rb') as fh:
                data = fh.read()
            for tok in tokenize.tokenize(io.BytesIO(data).readline):
                if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
                    results.append((rel, tok.start[0]))
        except Exception as e:
            print('skipped', rel, type(e).__name__)
results.sort()
with open('todos.txt', 'w') as out:
    for rel, line in results:
        out.write('%s:%d\n' % (rel, line))
print(len(results), 'occurrences')
